insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('0d325376-af89-4d3f-8820-ca6e89b33b16', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$inleiding — geleisuiker$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context1.png$$,
   $$Rian maakt aardbeienjam. Volgens haar recept moet ze gepureerde aardbeien vier minuten lang koken met wat citroensap en geleisuiker. Geleisuiker is een mengsel van suiker (sacharose), pectine en citroenzuur. Sacharose geeft de jam een zoete smaak. Ook bindt sacharose een groot deel van het water uit het fruit, waardoor micro-organismen in jam nauwelijks kunnen groeien en de jam lang houdbaar blijft. Op de uitwerkbijlage bij dit examen is de structuurformule van een sacharosemolecuul weergegeven.$$, 'inline'),
  ('c94a13d5-155f-4799-bd66-52202a4eb44e', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$uitwerkbijlage vraag 1 — structuurformule sacharose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context2.png$$,
   $$uitwerkbijlage bij vraag 1: de structuurformule van een sacharosemolecuul, opgebouwd uit twee via een zuurstofbrug gekoppelde ringstructuren met OH- en CH₂OH-groepen. Hierop moet de leerling twee watermoleculen tekenen die elk met een waterstofbrug aan het sacharosemolecuul zijn gebonden.$$, 'uitwerkbijlage'),
  ('f3d81aa9-e2aa-4756-81e0-ddf57d56fdc7', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$uitwerkbijlage vraag 2 — hydrolyse van sacharose (onvolledig)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context3.png$$,
   $$uitwerkbijlage bij vraag 2: de onvolledige reactievergelijking van de hydrolyse van sacharose, in structuurformules. Links staat de structuurformule van sacharose, gevolgd door een plusteken en puntjes (hier moet de leerling de structuurformule van de andere beginstof, water, invullen); na de reactiepijl staan twee lege blokken waarin de structuurformules van de twee reactieproducten getekend moeten worden.$$, 'uitwerkbijlage'),
  ('8b59101a-99f2-4801-9464-35b84c9303d8', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$figuur — fragment van een pectinemolecuul (monomeereenheid I en II)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context4.png$$,
   $$Het verdikkingsmiddel pectine maakt de jam minder vloeibaar. figuur: structuurformule van een fragment van een pectinemolecuul, opgebouwd uit vier na elkaar gekoppelde ringvormige monomeereenheden: monomeereenheid I (met een COOH-groep), monomeereenheid II (met een COOCH₃-groep, dus een estergroep), weer monomeereenheid II en ten slotte weer monomeereenheid I. Pectine is een copolymeer, gevormd uit monomeren van galacturonzuur (monomeereenheid I) en monomeren van stof II (monomeereenheid II). Stof II kan beschouwd worden als de ester van galacturonzuur en één andere stof.$$, 'inline'),
  ('b4cd2cdd-4519-4624-830d-eadce80b699c', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$figuur — netwerk van pectinemoleculen (bindingen 1 en 2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context5.png$$,
   $$Wanneer de jam na het koken afkoelt, vormt zich een netwerk van pectinemoleculen dat de andere stoffen insluit. Een dergelijk netwerk wordt een gel genoemd. figuur: schematische weergave van twee pectinemoleculen (met ester- en carboxylgroepen) die met elkaar verbonden zijn: binding 1 tussen een estergroep (C(=O)-O-CH₃) van het ene molecuul en een estergroep van het andere molecuul, en binding 2 (stippellijn) tussen een carboxylgroep (C(=O)-OH) van het ene molecuul en een carboxylgroep van het andere molecuul. Tussen de pectineketens zijn ook losse water- en suikermoleculen (kleine bolletjes, resp. zeshoekige ringen) ingesloten.$$, 'inline'),
  ('5687d4fd-3bde-4622-ac5d-5a3b0c87785f', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$citroensap — pH van de jam$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context6.png$$,
   $$Het citroensap dat Rian heeft toegevoegd, bevat een zuur dat de vorming van een gel bevordert en de pH rond 3,2 brengt.$$, 'inline'),
  ('8feb26b4-87df-4bed-9e08-e8beca14258d', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$structuurformule van het zuur in citroensap — beschrijving$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context7.png$$,
   $$De structuurformule van het zuur in citroensap is te omschrijven als propaan met op het eerste, tweede en derde koolstofatoom een carboxylgroep in plaats van een H-atoom. Ook bevindt zich aan het middelste koolstofatoom een hydroxylgroep in plaats van een H-atoom. De molecuulformule is C₆H₈O₇.$$, 'inline'),
  ('aa275864-49ac-47e9-9f91-d03a95a70cda', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$afwezigheid citroensap — hogere pH en COO⁻-groepen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context8.png$$,
   $$Als Rian vergeet om citroensap toe te voegen wordt de pH van de jam hoger dan 4,1. Bij deze hogere pH zal de meerderheid van de carboxylgroepen (COOH) in pectine zijn omgezet tot COO⁻-groepen. Zonder citroensap zullen er dus weinig tot geen carboxylgroepen zijn, waardoor de binding die in de figuur is aangeduid met cijfer 2 niet aanwezig is. De afwezigheid van deze binding zorgt ervoor dat de pectinemoleculen niet bij elkaar worden gehouden en er zich geen gel vormt. Tussen de COO⁻-groepen vindt zelfs een interactie plaats die gelvorming tegengaat.$$, 'inline'),
  ('953b39ca-3bb7-4590-b052-9a2b44ab1bed', '42d5c819-f910-4751-8345-f5d8bb606ab9', $$gewicht pectine in het potje jam$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-geleisuiker-context9.png$$,
   $$Rian heeft berekend dat een potje jam 1,6 gram pectine bevat.$$, 'inline'),
  ('258a4c6f-b2ff-4ab0-befa-f5547b6b5e27', '3da85657-15be-46a3-91ac-f06657c0c401', $$inleiding — kunststofafval en recycling$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context1.png$$,
   $$In Europa werd in 2016 van al het ingezamelde kunststofafval ongeveer 30% gerecycled. De rest van het kunststofafval belandde op de vuilnisbelt of werd verbrand. Sommige kunststoffen, zoals thermoharders, zijn moeilijk te recyclen.$$, 'inline'),
  ('bd9a82c4-ee13-4900-9be5-b29fc2344011', '3da85657-15be-46a3-91ac-f06657c0c401', $$figuur 1 — blokschema van kunststofafval tot methanol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context2.png$$,
   $$In de haven van Rotterdam wordt een fabriek gebouwd die niet-recyclebaar kunststofafval gaat omzetten tot waardevolle chemicaliën. Een voorbeeld is de vorming van de grondstof methanol. figuur 1: onvolledig blokschema van dit proces: kunststofafval → reactor R1 → gasmengsel → zuivering → synthesegas → reactor R2 → methanol.$$, 'inline'),
  ('74bb9459-23a5-48a6-b00d-173a03a0cca8', '3da85657-15be-46a3-91ac-f06657c0c401', $$reactor 1 — energie nodig voor de omzetting$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context3.png$$,
   $$In reactor 1 (R1) wordt kunststofafval omgezet tot een gasmengsel. Voor deze omzetting is energie nodig. Op de uitwerkbijlage is een onvolledig energiediagram weergegeven van deze reactie.$$, 'inline'),
  ('dc5167ae-526e-4278-a706-c18766c7664d', '3da85657-15be-46a3-91ac-f06657c0c401', $$uitwerkbijlage vraag 10 — onvolledig energiediagram van R1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context4.png$$,
   $$uitwerkbijlage bij vraag 10: een onvolledig energiediagram (energie op de y-as) van de omzetting van kunststofafval tot gasmengsel in reactor R1. Alleen het energieniveau van de beginstof (kunststofafval) is al ingetekend; het energieniveau van de reactieproducten, het energieniveau van de geactiveerde toestand en de reactiewarmte ontbreken nog en moeten worden aangevuld.$$, 'uitwerkbijlage'),
  ('453a27be-579a-4c0d-b43c-9e79f77387c4', '3da85657-15be-46a3-91ac-f06657c0c401', $$reactor 2 — vorming van methanol uit synthesegas$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context5.png$$,
   $$Het in R1 ontstane gasmengsel wordt vervolgens gezuiverd tot synthesegas: een mengsel van koolstofmono-oxide en waterstof. In reactor 2 (R2) wordt uit dit synthesegas methanol gevormd volgens onderstaande vergelijking.

CO + 2 H₂ → CH₃OH

Bij deze reactie komt warmte vrij.$$, 'inline'),
  ('60a1885b-3c4a-4f29-b61f-928122ad2051', '3da85657-15be-46a3-91ac-f06657c0c401', $$figuur 2 — warmtewisselaar$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context6.png$$,
   $$In een chemische fabriek zal de vrijgekomen reactiewarmte zo veel mogelijk elders in het proces weer gebruikt worden. Hierbij worden warmtewisselaars ingezet. figuur 2: schematische weergave van een warmtewisselaar (aangeduid met een cirkel met een M-vormig symbool erin): een stofstroom gaat er horizontaal doorheen (stofstroom in → stofstroom uit), terwijl er van onderaf twee aparte stromen warm of koud water in- en uitgaan.

Op de uitwerkbijlage is het blokschema uit figuur 1 weergegeven en uitgebreid met één warmtewisselaar. In dit blokschema ontbreekt een tweede warmtewisselaar.$$, 'inline'),
  ('2ef7f23a-2fcd-4eef-b58d-3a0638b7c517', '3da85657-15be-46a3-91ac-f06657c0c401', $$uitwerkbijlage vraag 12 — blokschema met warmtewisselaar$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context7.png$$,
   $$uitwerkbijlage bij vraag 12: het blokschema kunststofafval → R1 → gasmengsel → zuivering → synthesegas → R2 → methanol, waarbij na R2 al één warmtewisselaar (met twee niet-ingevulde water-aansluitingen, aangeduid met '…') is toegevoegd. De leerling moet de tweede warmtewisselaar intekenen en bij beide warmtewisselaars met pijlen de richting van de waterinvoer/-uitvoer en welke stroom warm/koud water bevat aangeven.$$, 'uitwerkbijlage'),
  ('4f767d78-98a8-46be-82ab-c4cef06acff1', '3da85657-15be-46a3-91ac-f06657c0c401', $$rendement — hoeveelheden kunststofafval en methanol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-van-kunststofafval-tot-grondstof-context8.png$$,
   $$De Rotterdamse fabriek kan 3,6·10⁵ ton kunststofafval verwerken tot 2,13·10⁵ ton methanol (1,0 ton = 1,0·10³ kg). Deze opbrengst is lager dan volgens de theorie te verwachten is.$$, 'inline'),
  ('fac572ba-d1ff-4da4-b88d-3ddf695b22aa', '799fee68-0598-41d5-bb7a-7374658611d0', $$Hb, HbO₂ en HbCO — binding van zuurstof en koolstofmono-oxide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-co-meting-context1.png$$,
   $$Koolstofmono-oxide is giftig doordat het zuurstof uit het lichaam verdringt. Bij inademing van schone lucht wordt zuurstof uit de lucht gebonden door het eiwit hemoglobine (Hb). Hierbij ontstaat oxyhemoglobine (HbO₂), dat zuurstof via de bloedbaan door het lichaam verspreidt. Wanneer lucht is verontreinigd met koolstofmono-oxide, wordt koolstofmono-oxide in plaats van zuurstof door Hb gebonden. Er ontstaat dan HbCO. Slechts een kleine concentratie koolstofmono-oxide leidt al tot een vergiftiging. Inademing van lucht die 0,10 volumeprocent koolstofmono-oxide bevat, leidt ertoe dat 50% van alle Hb-moleculen bindt met CO-moleculen en 50% van de Hb-moleculen bindt met O₂-moleculen.$$, 'inline'),
  ('acd47117-dd4b-4eab-bdcd-5ceef94d45f9', '799fee68-0598-41d5-bb7a-7374658611d0', $$figuur — verband tussen CO-gehalte in uitgeademde lucht en HbCO-gehalte in bloed$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-co-meting-context2.png$$,
   $$figuur: grafiek met op de horizontale as het CO-gehalte in de uitgeademde lucht (in volume-ppm, van 0 tot 220) en op de verticale as het HbCO-gehalte in bloed (in %, van 0 tot 40). Het verband is een rechte lijn door de oorsprong: bij CO-gehalte 0 is HbCO-gehalte 0%, bij CO-gehalte ongeveer 40 volume-ppm is het HbCO-gehalte ongeveer 6%, en de lijn loopt door tot ongeveer 36% HbCO bij 220 volume-ppm CO.$$, 'inline'),
  ('a7018c31-27a0-4b45-b7a0-1b0788a1bf1b', '799fee68-0598-41d5-bb7a-7374658611d0', $$gegevens — drempel CO-vergiftiging en meting bij een persoon$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-co-meting-context3.png$$,
   $$Bij een HbCO-gehalte van meer dan 12% is er sprake van CO-vergiftiging. Het CO-gehalte op de horizontale as is uitgedrukt in volume-ppm. 1 volume-ppm komt overeen met 1·10⁻⁶ liter koolstofmono-oxide per liter lucht. Bij een meting blijkt de uitgeademde lucht van een persoon 3,0·10² µg koolstofmono-oxide te bevatten. Het volume van de uitgeademde lucht van deze persoon was 4,0 L.$$, 'inline'),
  ('908d9057-add1-4317-b5e7-08f87aff7997', '799fee68-0598-41d5-bb7a-7374658611d0', $$halfreactie in de CO-meter$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-co-meting-context4.png$$,
   $$De werking van de CO-meter is gebaseerd op een redoxreactie in een elektrochemische cel. De uitgeademde lucht wordt langs een van de elektroden geleid. Het CO wordt daarbij omgezet tot CO₂ volgens onderstaande halfreactie.

H₂O + CO → 2 H⁺ + CO₂ + 2 e⁻

Aan de andere elektrode van de CO-meter reageert zuurstof. Bij deze omzetting reageren ook H⁺-ionen.$$, 'inline'),
  ('5643053d-d1fb-45cb-9688-2ab5b0c6e166', '799fee68-0598-41d5-bb7a-7374658611d0', $$behandeling CO-vergiftiging — halveringstijd van HbCO in het bloed$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-co-meting-context5.png$$,
   $$Iemand met een CO-vergiftiging moet snel schone lucht inademen die geen koolstofmono-oxide bevat. CO-moleculen die loslaten van Hb-moleculen worden dan verdrongen door de overmaat aan O₂-moleculen die wordt ingeademd. De vrijgekomen Hb-moleculen binden vervolgens O₂-moleculen in plaats van CO-moleculen. De snelheid waarmee de concentratie HbCO in het bloed afneemt is zodanig dat elke 5 uur de concentratie HbCO halveert. De concentratie HbCO in het bloed van een patiënt is 2,28 mmol L⁻¹.$$, 'inline'),
  ('01e0ae0e-3604-4e3b-be69-61a6d5b0a9b9', '799fee68-0598-41d5-bb7a-7374658611d0', $$nadeel van inademen van lucht — beademen met zuivere zuurstof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-co-meting-context6.png$$,
   $$Een nadeel van de inademing van lucht is dat het lang duurt voordat de concentratie HbCO op een niet-giftig niveau is gekomen. Bij ernstige CO-vergiftiging wordt daarom vaak beademd met zuivere zuurstof. De tijd die nodig is om de concentratie HbCO te halveren wordt dan teruggebracht tot 1,0 uur.$$, 'inline'),
  ('da253738-d429-4cad-8edc-fdb42e9dc223', '5c007806-f7b2-484b-9234-5b10c044b2cc', $$figuur 1 — elektrodialyse-opstelling met membranen A en B$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-zonlicht-maakt-zout-water-zoet-context1.png$$,
   $$Voor het verbouwen van gewassen zoals rijst is veel water nodig. Grondwater bevat vaak te veel opgeloste zouten om het water voor gewasteelt te kunnen gebruiken. Deze zouten moeten worden verwijderd. Hierna wordt het water 'zoet water' genoemd. Destillatie van grote hoeveelheden grondwater kost veel energie en is duur. Een mogelijk alternatief is elektrodialyse. Bij elektrodialyse stroomt zout grondwater door een opstelling met membranen waarover een spanning is aangelegd. De benodigde elektrische energie wordt met behulp van zonlicht opgewekt.

figuur 1: de elektrodialyse-opstelling met zes compartimenten, gescheiden door afwisselend membraan A (laat uitsluitend positieve ionen door) en membraan B (laat uitsluitend negatieve ionen door), met een positieve elektrode (+) links en een negatieve elektrode (−) rechts. Zout grondwater stroomt van onderaf de opstelling in. Er stromen twee vloeistoffen uit: vloeistofstroom 1 (uit de compartimenten grenzend aan de elektroden) en vloeistofstroom 2 (uit de middelste compartimenten), naast twee gescheiden elektrolytstromen langs de elektroden.

In figuur 1 is weergegeven hoe zout grondwater van onderaf de opstelling met zes compartimenten binnenstroomt. Na inschakelen van de spanningsbron kunnen de ionen die in het zoute water aanwezig zijn zich door een membraan verplaatsen. Doordat de membranen A en B afwisselend zijn geplaatst, vindt in sommige compartimenten een verwijdering van ionen plaats en in andere compartimenten een toename van de concentratie van ionen. Er stromen dus twee vloeistoffen uit de opstelling: zoet water en zeer zout water.$$, 'inline'),
  ('397054ae-3062-49a1-8a5e-db11ac41002c', '5c007806-f7b2-484b-9234-5b10c044b2cc', $$uitwerkbijlage vraag 21 — ionen bij de membranen intekenen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-zonlicht-maakt-zout-water-zoet-context2.png$$,
   $$uitwerkbijlage bij vraag 21: dezelfde elektrodialyse-opstelling als in figuur 1, met in de middelste vier compartimenten telkens een Na⁺-ion en een Cl⁻-ion getekend (vóór het inschakelen van de spanningsbron). De leerling moet aangeven welke van deze ionen zich door een membraan (A of B) verplaatsen na het inschakelen van de spanningsbron, met een pijl voor de richting van de verplaatsing.$$, 'uitwerkbijlage'),
  ('09aadbc9-0bea-4102-908c-19b8f409cbe1', '5c007806-f7b2-484b-9234-5b10c044b2cc', $$halfreactie 1 en de elektrolyt-oplossing (Na₂SO₄)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-zonlicht-maakt-zout-water-zoet-context3.png$$,
   $$Aan de negatieve elektrode ontstaat waterstof volgens halfreactie 1. Als deze waterstof wordt opgeslagen, kan die gebruikt worden voor een brandstofcel die 's nachts de opstelling van energie voorziet. De waterstof wordt gevormd volgens onderstaande halfreactie:

2 H₂O + 2 e⁻ → H₂ + 2 OH⁻ (halfreactie 1)

Langs beide elektroden wordt een elektrolyt-oplossing geleid. Hiervoor wordt een oplossing van natriumsulfaat (Na₂SO₄) gebruikt.$$, 'inline'),
  ('ac9c09f3-285a-4daf-9a42-baed19c27ee4', '5c007806-f7b2-484b-9234-5b10c044b2cc', $$chloride-ionen bij de positieve elektrode — GHS-gevarenzin H330$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-zonlicht-maakt-zout-water-zoet-context4.png$$,
   $$In de opstelling van figuur 1 wordt voorkómen dat chloride-ionen in de elektrolyt-oplossing aan de positieve elektrode komen. Dit voorkomt het optreden van een ongewenste halfreactie van Cl⁻ aan deze elektrode. Volgens het GHS-systeem zou dan gevarenzin H330 van toepassing zijn.$$, 'inline'),
  ('7572014e-75f0-4075-8c4f-c68463920402', '5c007806-f7b2-484b-9234-5b10c044b2cc', $$figuur 2 — additiepolymeer membraan met monomeer 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-zonlicht-maakt-zout-water-zoet-context5.png$$,
   $$In figuur 2 is de structuurformule weergegeven van een additiepolymeer waaruit een van de twee soorten membranen uit de opstelling is gemaakt. Dit additiepolymeer is gevormd uit twee soorten monomeren. Een van de monomeren is ook apart in figuur 2 weergegeven. Het andere monomeer zorgt voor crosslinks tussen de ketens van het polymeer.

figuur 2: links de structuurformule van het polymeer, opgebouwd uit herhaalde eenheden met een zesring die een C=C-binding, een SO₃⁻Na⁺-groep en een crosslink (verticale binding) tussen twee ketens bevat; rechts apart 'monomeer 1': een zesring met een C=C-binding, een vinylgroep (CH=CH₂) en een SO₃⁻Na⁺-groep.$$, 'inline'),
  ('b7f439cc-d720-4194-80a5-6bd18b5be71d', '5c007806-f7b2-484b-9234-5b10c044b2cc', $$elektrodialyse versus destillatie — energiegegevens$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-zonlicht-maakt-zout-water-zoet-context6.png$$,
   $$Een belangrijk voordeel van elektrodialyse is het lage energieverbruik. Met 2,3 kWh aan energie kan 1,0 m³ zout grondwater worden gezuiverd. De benodigde energie kan bovendien met zonlicht worden opgewekt. Bij het destilleren van zout grondwater ligt het energieverbruik veel hoger, doordat veel energie nodig is om water te laten verdampen. Met behulp van onderstaande gegevens kan worden berekend dat met 2,3 kWh aan energie via destillatie veel minder dan 1,0 m³ zout grondwater gezuiverd kan worden.
Gegevens:
− 1,0 kWh komt overeen met 3,6·10⁶ J.
− De verdampingsenergie van zout grondwater is 2,26·10⁶ J per kg.
− De dichtheid van zout grondwater is 1,02·10³ kg m⁻³.$$, 'inline'),
  ('b67d9d30-6486-4f5b-9193-58a710bcaed7', '0957555c-52cc-4f0e-b5b6-952b47b22976', $$omzetting van cysteïne tot diwaterstofsulfide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-kringloop-context1.png$$,
   $$Planten maken de zwavelbevattende aminozuren cysteïne en methionine uit sulfaationen. Deze ionen worden opgenomen uit de bodem. Door het eten van planten krijgen mensen deze aminozuren binnen. In het menselijk lichaam worden vrijwel alle zwavelbevattende stoffen gemaakt uit de aminozuren cysteïne of methionine. Zo wordt de stof diwaterstofsulfide, die helpt de bloeddruk te reguleren, gemaakt uit cysteïne. Deze omzetting is hieronder schematisch weergegeven.

cysteïne + H₂O → aminozuur X + H₂S$$, 'inline'),
  ('787dc115-2dc8-4a0c-8feb-333b0a5f2d07', '0957555c-52cc-4f0e-b5b6-952b47b22976', $$glutathion — Glu*-Cys-Gly, opmerkelijke binding van glutaminezuur aan cysteïne$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-kringloop-context2.png$$,
   $$Het lichaam bewaart cysteïne door het om te zetten tot glutathion en dit vervolgens op te slaan. Glutathion is een verbinding van de aminozuren glutaminezuur, cysteïne en glycine. Glutathion kan worden weergegeven als:

Glu*-Cys-Gly

Hierbij is het aminozuur glutaminezuur weergegeven als Glu*, omdat dit aminozuur op een opmerkelijke manier aan cysteïne is gebonden. De carboxylgroep van de restgroep van glutaminezuur is gebonden aan de aminogroep van cysteïne. Cysteïne en glycine zijn wel op de gebruikelijke manier aan elkaar gebonden.$$, 'inline'),
  ('dd8cd62e-2dd7-4204-837f-fa424744d02e', '0957555c-52cc-4f0e-b5b6-952b47b22976', $$overschot zwavelbevattende aminozuren — sulfaationen en carbonylsulfide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-kringloop-context3.png$$,
   $$Het overschot aan zwavelbevattende aminozuren wordt in het lichaam van mensen en dieren omgezet tot sulfaationen die via de urine worden uitgescheiden. Deze ionen kunnen via het grondwater door planten worden opgenomen, maar kunnen ook via het oppervlaktewater in zee belanden. In zee kunnen de sulfaationen worden omgezet tot organische verbindingen. Bij de afbraak van deze verbindingen ontstaan vluchtige zwavelbevattende stoffen, zoals carbonylsulfide. De molecuulformule van carbonylsulfide is COS.$$, 'inline'),
  ('fa2da557-d03b-4299-af6a-8fd24f89071d', '0957555c-52cc-4f0e-b5b6-952b47b22976', $$vluchtige zwavelbevattende stoffen worden omgezet tot zwaveldioxide en sulfaationen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-kringloop-context4.png$$,
   $$De vluchtige zwavelbevattende stoffen komen vrij uit de oceaan en worden in de atmosfeer omgezet tot zwaveldioxide. Vervolgens worden de zwaveldioxidemoleculen in een reactie met andere moleculen omgezet tot sulfaationen. De sulfaationen komen, met bijvoorbeeld regen, in de bodem terecht.$$, 'inline'),
  ('f5031ccd-5ced-437c-a65e-1a4ff54fdd4b', '0957555c-52cc-4f0e-b5b6-952b47b22976', $$toelichting bij het kringloopschema op de uitwerkbijlage$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-kringloop-context5.png$$,
   $$Het gedeelte van de kringloop dat in deze opgave wordt beschreven, is op de uitwerkbijlage vereenvoudigd en onvolledig weergegeven. De verschillende zwavelbevattende stoffen ontbreken en de richting van vier stofstromen is niet aangegeven.$$, 'inline'),
  ('2f39cc25-2a30-4775-b193-f817ef25b3a9', '0957555c-52cc-4f0e-b5b6-952b47b22976', $$uitwerkbijlage vraag 32 — kringloopschema (atmosfeer, mens/dier, plant, grondwater, oppervlaktewater/zee)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-iii-kringloop-context6.png$$,
   $$uitwerkbijlage bij vraag 32: een vereenvoudigd en onvolledig kringloopschema met vijf compartimenten: 'atmosfeer' (bovenaan), 'oppervlaktewater/zee' (rechts), een compartiment met plant, mens en dieren (koe, konijn, schaap; onderaan) en 'grondwater' (onderaan). Tussen de compartimenten lopen ongerichte lijnen (zonder pijlpunt) en één lijn met stippellijn, elk met een niet-ingevulde stippellijn ('…') waarop het nummer van de juiste stof, stofgroep of ionsoort (1 t/m 4) moet worden ingevuld; ook moeten alle lijnen van pijlen worden voorzien die de juiste richting van de stofstromen aangeven.$$, 'uitwerkbijlage');

