  ('d9f2e715-0c0d-4400-b626-9486f91c2781', '3da85657-15be-46a3-91ac-f06657c0c401', 13,
   $$[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]$$::jsonb,
   $$["rendement", "massaprocent", "koolstof", "molverhouding"]$$::jsonb,
   $$Rendement van de omzetting van kunststofafval naar methanol berekenen$$,
